const PATTERNS = {
  fr: [
    [/^(\d+(?:[.,]\d+)?) °C mean surface temperature$/, "$1 °C de température moyenne de surface"],
    [/^(\d+) annual summer surface temperature maps$/, "$1 cartes annuelles de température de surface estivale"],
    [/^(\d+) annual exceptionally hot area maps$/, "$1 cartes annuelles des zones exceptionnellement chaudes"],
    [/^(\d+) observations (.+)$/, "$1 observations $2"],
    [/^Average usable coverage: (.+) of the city\.$/, "Couverture utile moyenne : $1 de la ville."],
    [/^Best observation: (.+) of the city readable\.$/, "Meilleure observation : $1 de la ville lisible."],
    [/^The orthophoto basemap uses the validated IGN\/Géoplateforme (.+) for Marseille\. It is a contextual basemap, not a year-by-year historical orthophoto series: all summers are shown over the same current high-resolution imagery, constrained to the Marseille map extent\.$/, (years) => `Le fond orthophoto utilise l'orthophoto IGN/Géoplateforme ${years} validée pour Marseille. C'est un fond contextuel, pas une série historique d'orthophotos année par année : tous les étés sont affichés sur la même image actuelle à haute résolution, limitée à l'emprise de la carte de Marseille.`],
    [/^Marseille (\d+)(er|e) Arrondissement$/, (number, suffix) => `${number}${suffix} arrondissement de Marseille`],
    [/^#(\d+) by (.+)$/, "#$1 selon $2"],
    [/^(\d+) years$/, "$1 ans"],
    [/^(\d+) year$/, "$1 an"],
    [/^(\d+) anomalous years$/, "$1 années anormales"],
    [/^(\d+) anomalous year$/, "$1 année anormale"],
    [/^0 anomalous years$/, "0 année anormale"],
    [/^(\d+) chronic years$/, "$1 années chroniques"],
    [/^(\d+) chronic year$/, "$1 année chronique"],
    [/^0 chronic years$/, "0 année chronique"],
    [/^(\d+) chronic, (\d+) anomalous$/, "$1 chroniques, $2 anormales"],
    [/^(\d+) chronic years, (\d+) anomalous years\.$/, "$1 années chroniques, $2 années anormales."],
    [/^Summer \*\*([^*]+)\*\* compared with the 2013-2026 historical average, with (.+)\.$/, (mood, exceptional) => `Été **${phrase("fr", mood)}** par rapport à la moyenne historique 2013-2026, avec ${phrase("fr", exceptional)}.`],
    [/^Summer \*\*([^*]+)\*\*: the one with the highest mean surface temperature in the 2013-2026 series, with (.+)\.$/, (mood, exceptional) => `Été **${phrase("fr", mood)}** : celui qui présente la température moyenne de surface la plus élevée de la série 2013-2026, avec ${phrase("fr", exceptional)}.`],
    [/^One of the summers with the lowest mean surface temperature in the 2013-2026 series, with (.+)\.$/, (exceptional) => `L'un des étés avec la température moyenne de surface la plus basse de la série 2013-2026, avec ${phrase("fr", exceptional)}.`],
    [/^This point is structurally hot compared with the city and shows (.+) compared with its own history\.$/, (signal) => `Ce point est structurellement chaud par rapport à la ville et montre ${phrase("fr", signal)} par rapport à sa propre histoire.`],
    [/^This point shows (.+) compared with its own history, without being one of Marseille's areas with the structurally highest surface temperature\.$/, (signal) => `Ce point montre ${phrase("fr", signal)} par rapport à sa propre histoire, sans faire partie des zones de Marseille avec la température de surface structurellement la plus élevée.`],
    [/^Summary of the summer satellite overpasses used to build the (\d{4}) map\.$/, "Résumé des passages satellitaires estivaux utilisés pour construire la carte $1."],
    [/^(\d+) 1 km cells intersecting Marseille$/, "$1 cellules de 1 km qui recoupent Marseille"],
    [/^Showing (\d+)-(\d+) of (\d+) statistical areas$/, "Affichage $1-$2 sur $3 quartiers"],
    [/^Page (\d+)$/, "Page $1"],
    [/^(\d+)-(\d+) years$/, "$1-$2 ans"],
    [/^(\d+)-(\d+) chronic years$/, "$1-$2 années chroniques"],
    [/^(\d+)-(\d+) anomalous years$/, "$1-$2 années anormales"],
    [/^(surface|vegetation|day-night range|reflectance): (absorbing|medium|reflective|sparse|moderate|dense|lower|wider|-?\d+(?:\.\d+)?)$/, (title, value) => `${TRANSLATIONS.fr[title] || title}: ${TRANSLATIONS.fr[value] || value}`],
    [/^n\/a\s?(%|°C)$/, "n.d."],
  ],
};

function phrase(language, value) {
  return PHRASES[language]?.[value] || value;
}

function translateExact(language, text) {
  const dictionary = TRANSLATIONS[language];
  if (!dictionary) return text;
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  const trimmed = text.trim();
  const translated = dictionary[trimmed];
  if (translated) return `${leading}${translated}${trailing}`;
  for (const [pattern, replacement] of PATTERNS[language] || []) {
    const match = trimmed.match(pattern);
    if (!match) continue;
    const result = typeof replacement === "function"
      ? replacement(...match.slice(1))
      : trimmed.replace(pattern, replacement);
    return `${leading}${result}${trailing}`;
  }
  return text;
}

export function translateUiText(language, value) {
  if (value == null) return value;
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage === "it" || normalizedLanguage === "en") return value;
  return translateExact(normalizedLanguage, String(value));
}

export function translateUiTree(language, root = document.body) {
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage !== DEFAULT_LANGUAGE || !root) return;

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  for (const node of textNodes) {
    const translated = translateUiText(normalizedLanguage, node.nodeValue);
    if (translated !== node.nodeValue) node.nodeValue = translated;
  }

  const attributes = ["aria-label", "title", "placeholder"];
  root.querySelectorAll?.("*").forEach((element) => {
    for (const attribute of attributes) {
      const value = element.getAttribute(attribute);
      if (!value) continue;
      const translated = translateUiText(normalizedLanguage, value);
      if (translated !== value) element.setAttribute(attribute, translated);
    }
  });
}

export function setupUiTranslations(language) {
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage !== DEFAULT_LANGUAGE) return () => {};
  let rafId = null;
  const apply = () => {
    rafId = null;
    translateUiTree(normalizedLanguage);
  };
  const schedule = () => {
    if (rafId != null) return;
    rafId = requestAnimationFrame(apply);
  };
  schedule();
  const observer = new MutationObserver(schedule);
  observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["aria-label", "title", "placeholder"],
  });
  return () => {
    if (rafId != null) cancelAnimationFrame(rafId);
    observer.disconnect();
  };
}
